/* =========================================
   INCIDENT DASHBOARD — IncidentDashboard.css
   Extends Management.css + Users.css patterns.
   ========================================= */

/* --- Summary Stat Cards --- */
.inc-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.inc-stat-card {
  background: #1e2539;
  border: 1px solid #2d364f;
  border-radius: 12px;
  padding: 22px 24px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s, border-color 0.2s;
}

.inc-stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
}

.inc-stat-card:hover {
  transform: translateY(-2px);
  border-color: #334155;
}

.inc-stat-blue::before  { background: #3b82f6; }
.inc-stat-red::before   { background: #f87171; }
.inc-stat-orange::before { background: #f59e0b; }
.inc-stat-green::before  { background: #34d399; }

.inc-stat-blue  { border-left: 4px solid #3b82f6; }
.inc-stat-red   { border-left: 4px solid #f87171; }
.inc-stat-orange { border-left: 4px solid #f59e0b; }
.inc-stat-green  { border-left: 4px solid #34d399; }

/* Override the ::before left bar since we're using border-left */
.inc-stat-card::before { display: none; }

.inc-stat-value {
  font-size: 2.2rem;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1;
  margin-bottom: 6px;
}

.inc-stat-blue  .inc-stat-value { color: #60a5fa; }
.inc-stat-red   .inc-stat-value { color: #f87171; }
.inc-stat-orange .inc-stat-value { color: #f59e0b; }
.inc-stat-green  .inc-stat-value { color: #34d399; }

.inc-stat-label {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  color: #64748b;
}

/* --- AI vs Manual source counter chips --- */
.inc-source-counter {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}

.inc-source-chip {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  white-space: nowrap;
  border: 1px solid;
}

.inc-source-chip-ai {
  background: rgba(192, 132, 252, 0.10);
  color: #c084fc;
  border-color: rgba(192, 132, 252, 0.25);
}

