/* Exit animation: collapse height + fade out, table slides back up */
@keyframes incToastExit {
  from {
    max-height: 80px;
    opacity: 1;
    padding-top: 11px;
    padding-bottom: 11px;
    margin-bottom: 8px;
  }
  to {
    max-height: 0;
    opacity: 0;
    padding-top: 0;
    padding-bottom: 0;
    margin-bottom: 0;
  }
}

.inc-toast-item {
  overflow: hidden;
  border-radius: 8px;
  border-left: 3px solid;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0 16px;
  box-sizing: border-box;
  animation: incToastEnter 0.35s ease forwards;
  will-change: max-height, opacity;
}

.inc-toast-item.removing {
  animation: incToastExit 0.35s ease forwards;
}

